const setProblemVerdictAndAdoption = `-- name: SetProblemVerdictAndAdoption :one
UPDATE regrade_request_problems
SET verdict = $2, verdict_note = $3, verdict_by = $4, verdict_at = now(),
    adopted_record_id = $5
WHERE id = $1
RETURNING id, request_id, problem_id, complaint_text, ai_record_id, ai_error, verdict, verdict_note, verdict_by, verdict_at, created_at, adopted_record_id
`

type SetProblemVerdictAndAdoptionParams struct {
	ID              int64       `json:"id"`
	Verdict         pgtype.Text `json:"verdict"`
	VerdictNote     string      `json:"verdict_note"`
	VerdictBy       pgtype.Int8 `json:"verdict_by"`
	AdoptedRecordID pgtype.Int8 `json:"adopted_record_id"`
}

// SetProblemVerdictAndAdoption records a TA's adjudication AND its overlay in ONE
// atomic statement (regrade-round correctness fix): the old handler ran SetProblemVerdict
// then SetSubItemAdoptedRecord as two writes, so a failure between them could strand a
// verdict='upheld' row still carrying a stale adopted_record_id — an override overlay
// consumers would apply for a grade the student was never told about. Setting verdict,
// note, who, when, and adopted_record_id together makes the pair all-or-nothing:
// adopted_record_id carries the record for a 'regraded' verdict, or SQL NULL (narg) for
// 'upheld'.
func (q *Queries) SetProblemVerdictAndAdoption(ctx context.Context, arg SetProblemVerdictAndAdoptionParams) (RegradeRequestProblem, error) {
	row := q.db.QueryRow(ctx, setProblemVerdictAndAdoption,
		arg.ID,
		arg.Verdict,
		arg.VerdictNote,
		arg.VerdictBy,
		arg.AdoptedRecordID,
	)
	var i RegradeRequestProblem
	err := row.Scan(
		&i.ID,
		&i.RequestID,
		&i.ProblemID,
		&i.ComplaintText,
		&i.AiRecordID,
		&i.AiError,
		&i.Verdict,
		&i.VerdictNote,
		&i.VerdictBy,
		&i.VerdictAt,
		&i.CreatedAt,
		&i.AdoptedRecordID,
	)
	return i, err
}

