const studentOfficialTotalForProblem = `-- name: StudentOfficialTotalForProblem :one
SELECT
    coalesce(sum(gr.total), 0)::numeric AS total,
    coalesce((SELECT p.max_points FROM problems p WHERE p.id = $2), 0)::numeric AS max,
    count(a.official_record_id) AS graded
FROM answers a
LEFT JOIN grading_records gr ON gr.id = a.official_record_id
WHERE a.student_id = $1 AND a.problem_id = $2
`

type StudentOfficialTotalForProblemParams struct {
	StudentID int64 `json:"student_id"`
	ID        int64 `json:"id"`
}

type StudentOfficialTotalForProblemRow struct {
	Total  pgtype.Numeric `json:"total"`
	Max    pgtype.Numeric `json:"max"`
	Graded int64          `json:"graded"`
}

// A student's current official (score, max) for ONE problem, straight from live grading
// state -- the fresh figure the result email announces for a REGRADED verdict (C2:
// never the superseded snapshot the token was minted against). graded counts whether
// the answer carries an official record; zero means nothing is official for this
// (student, problem) yet, so the caller omits the New-score line rather than announcing
// "0/max".
func (q *Queries) StudentOfficialTotalForProblem(ctx context.Context, arg StudentOfficialTotalForProblemParams) (StudentOfficialTotalForProblemRow, error) {
	row := q.db.QueryRow(ctx, studentOfficialTotalForProblem, arg.StudentID, arg.ID)
	var i StudentOfficialTotalForProblemRow
	err := row.Scan(&i.Total, &i.Max, &i.Graded)
	return i, err
}

const upsertRegradeRoundMethod = `-- name: UpsertRegradeRoundMethod :one
INSERT INTO regrade_round_methods (assessment_id, turn, method_id)
VALUES ($1, $2, $3)
ON CONFLICT (assessment_id, turn) DO UPDATE
    SET method_id = EXCLUDED.method_id, updated_at = now()
RETURNING assessment_id, turn, method_id, updated_at
`

type UpsertRegradeRoundMethodParams struct {
	AssessmentID int64 `json:"assessment_id"`
	Turn         int32 `json:"turn"`
	MethodID     int64 `json:"method_id"`
}

// Per-round regrade methods (0027): one method per email turn, preset on the
// Regrade tab, usually a single strict model.
func (q *Queries) UpsertRegradeRoundMethod(ctx context.Context, arg UpsertRegradeRoundMethodParams) (RegradeRoundMethod, error) {
	row := q.db.QueryRow(ctx, upsertRegradeRoundMethod, arg.AssessmentID, arg.Turn, arg.MethodID)
	var i RegradeRoundMethod
	err := row.Scan(
		&i.AssessmentID,
		&i.Turn,
		&i.MethodID,
		&i.UpdatedAt,
	)
	return i, err
}
